let firebaseBootPromise=Promise.resolve(false);

async function firebaseInit(config, announce=false) {
  if (!validConfig(config)) return false;
  if(state.firebase){if(announce)showToast('Firebase đã kết nối trong phiên này. Tải lại trang để thay đổi dự án.');return true}
  try {
    const sdk='13.2.0';
    const [appMod,authMod,storeMod] = await Promise.all([
      import(`https://www.gstatic.com/firebasejs/${sdk}/firebase-app.js`),
      import(`https://www.gstatic.com/firebasejs/${sdk}/firebase-auth.js`),
      import(`https://www.gstatic.com/firebasejs/${sdk}/firebase-firestore.js`)
    ]);
    let funcMod=null;
    try{funcMod=await import(`https://www.gstatic.com/firebasejs/${sdk}/firebase-functions.js`)}catch(error){console.warn('Firebase Functions chưa tải được; đăng nhập vẫn hoạt động.',error)}
    const app = appMod.getApps().length ? appMod.getApp() : appMod.initializeApp(config);
    let aiMod=null,ai=null,appCheckMod=null,appCheck=null;
    try{
      appCheckMod=await import(`https://www.gstatic.com/firebasejs/${sdk}/firebase-app-check.js`);
      if(config.appCheckSiteKey)appCheck=appCheckMod.initializeAppCheck(app,{provider:new appCheckMod.ReCaptchaEnterpriseProvider(config.appCheckSiteKey),isTokenAutoRefreshEnabled:true});
    }catch(error){console.warn('Firebase App Check chưa sẵn sàng.',error)}
    try{aiMod=await import(`https://www.gstatic.com/firebasejs/${sdk}/firebase-ai.js`);ai=aiMod.getAI(app,{backend:new aiMod.GoogleAIBackend(),useLimitedUseAppCheckTokens:true})}catch(error){console.warn('Firebase AI Logic chưa sẵn sàng.',error)}
    const auth = authMod.getAuth(app);
    const db = storeMod.getFirestore(app);
    const functions = funcMod?.getFunctions(app)||null;
    state.firebase = {app,auth,db,functions,authMod,storeMod,funcMod,aiMod,ai,appCheckMod,appCheck};
    $('#firebaseIndicator').textContent='● Firebase đã kết nối';$('#firebaseIndicator').classList.add('connected');$('#firebaseStatus').textContent='● Firebase đã kết nối';$('#firebaseStatus').className='status status-live';
    authMod.onAuthStateChanged(auth, async user => {
      if (!user) { if (state.user?.uid) signOutToAuth(); return; }
      if(state.signingUp)return;
      if(state.user?.uid&&state.user.uid!==user.uid)signOutToAuth();
      try {
        const userRef=storeMod.doc(db,'users',user.uid);
        const snap=await storeMod.getDoc(userRef);
        let profile=snap.exists()?snap.data():null;
        if(!profile){
          profile={name:user.displayName||user.email||'Nhân viên',email:user.email||'',role:'employee',approved:true};
          await storeMod.setDoc(userRef,{...profile,createdAt:storeMod.serverTimestamp()});
        }
        const token=await user.getIdTokenResult();
        if(state.firebase.auth.currentUser?.uid!==user.uid)return;
        state.user={uid:user.uid,email:user.email,name:profile.name||user.displayName||user.email,department:profile.department||'',branch:profile.branch||profile.branchName||profile.branchId||'',photoData:profile.photoData||'',role:profile.role||token.claims.role||'employee',approved:true};state.role=state.user.role;enterApp();
      } catch(e){console.error(e);showAuthNotice(authErrorMessage(e))}
    });
    if(announce)showToast('Đã kết nối Firebase. Bật Email/Password và triển khai Firestore Rules.');
    return true;
  } catch(error) {
    console.error(error);if(announce)showToast('Không kết nối được Firebase: '+(error.message||'kiểm tra cấu hình và hosting HTTPS'),'error');return false;
  }
}
async function saveRecord(collection,data,id=crypto.randomUUID()) {
  if(!state.firebase)return id;
  const {db,storeMod}=state.firebase;
  await storeMod.setDoc(storeMod.doc(db,'workspaces','fbtq',collection,id),{...data,updatedAt:storeMod.serverTimestamp(),updatedBy:state.user?.uid||null,createdBy:data.createdBy||state.user?.uid||null},{merge:true});
  return id;
}
async function callFunction(name,data) {
  if(!state.firebase?.funcMod)throw new Error('Dịch vụ Functions chưa kết nối. Đăng nhập vẫn dùng được; quản trị viên cần kiểm tra Firebase Functions.');
  const callable=state.firebase.funcMod.httpsCallable(state.firebase.functions,name);
  try{const result=await callable(data);return result.data}catch(error){if(error.code==='functions/not-found')throw new Error(name==='synthesizeSpeech'?'Chức năng giọng đọc chưa được triển khai. Quản lý cần lưu GEMINI_API_KEY và triển khai hàm synthesizeSpeech.':'Mô hình AI này chưa được khởi tạo. Quản lý cần lưu API Key và triển khai hàm tương ứng.');throw error}
}
function requireFirebaseAI(){
  if(!state.firebase?.aiMod||!state.firebase.ai)throw new Error('Firebase AI Logic chưa khởi tạo. Kiểm tra đã bật Firebase AI Logic với Gemini Developer API trong Firebase Console chưa.');
  if(!state.firebase.appCheck)throw new Error('Cần cấu hình App Check trước khi dùng Gemini: tạo reCAPTCHA Enterprise site key cho tên miền website, nhập vào Cài đặt → Firebase & dữ liệu, lưu rồi tải lại trang.');
  return state.firebase;
}
function isTemporaryGeminiCapacityError(error){const message=String(error?.message||error||'').toLowerCase();return /\b500\b|high demand|overload|temporarily unavailable|service unavailable|\b503\b|\b504\b|internal server error/.test(message)}
async function generateGeminiContent({prompt,tone,length}){
  const {aiMod,ai}=requireFirebaseAI();geminiFallbackUsed=false;
  const brandVoice=$('#brandVoice').value.trim()||'Thân thiện, rõ ràng, tích cực. Không tự tạo số liệu, giá bán hoặc cam kết chưa có trong yêu cầu.';
  const systemInstruction=`Bạn là trợ lý nội dung marketing của công ty FBTQ. Viết bằng tiếng Việt tự nhiên. Giọng thương hiệu: ${brandVoice}.\nGiọng điệu mong muốn: ${tone}. Độ dài: ${length}. Viết độc lập, không tự mặc định một nền tảng cụ thể.\nTuân thủ chính sách quảng cáo và tránh khẳng định sức khoẻ, tài chính hoặc kết quả tuyệt đối. Không tự thêm thông tin giá, ưu đãi, tồn kho hay số liệu nếu người dùng không cung cấp. Chỉ trả về nội dung có thể chỉnh sửa, không giải thích quy trình.`;
  const attempts=[{model:'gemini-3.8-flash',wait:0},{model:'gemini-3.8-flash',wait:1100},{model:'gemini-3.5-flash-lite',wait:0}];let lastError;
  for(let i=0;i<attempts.length;i++){
    const attempt=attempts[i];if(attempt.wait)await new Promise(resolve=>setTimeout(resolve,attempt.wait));
    try{
      const model=aiMod.getGenerativeModel(ai,{model:attempt.model,systemInstruction,generationConfig:{temperature:0.75,maxOutputTokens:length==='Chi tiết'?1500:900}});
      const result=await model.generateContent(prompt.trim()),content=result.response.text().trim();
      if(!content)throw new Error('Gemini không trả về nội dung. Hãy thử prompt khác.');
      geminiFallbackUsed=attempt.model!=='gemini-3.8-flash';return content;
    }catch(error){lastError=error;if(!isTemporaryGeminiCapacityError(error)||i===attempts.length-1)throw error;console.warn(`Gemini ${attempt.model} đang tạm quá tải; sẽ thử phương án tiếp theo.`,error)}
  }
  throw lastError||new Error('Không tạo được nội dung Gemini.');
}
function pcmToWav(pcmBytes,sampleRate=24000,channels=1,bitsPerSample=16){
  const headerSize=44,buffer=new ArrayBuffer(headerSize+pcmBytes.length),view=new DataView(buffer),bytes=new Uint8Array(buffer);
  const writeText=(offset,value)=>{for(let i=0;i<value.length;i++)view.setUint8(offset+i,value.charCodeAt(i))};
  const blockAlign=channels*bitsPerSample/8;
  writeText(0,'RIFF');view.setUint32(4,36+pcmBytes.length,true);writeText(8,'WAVE');writeText(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,channels,true);view.setUint32(24,sampleRate,true);view.setUint32(28,sampleRate*blockAlign,true);view.setUint16(32,blockAlign,true);view.setUint16(34,bitsPerSample,true);writeText(36,'data');view.setUint32(40,pcmBytes.length,true);bytes.set(pcmBytes,headerSize);
  return new Blob([buffer],{type:'audio/wav'});
}
async function generateGeminiSpeech(text,voice){
  const {aiMod,ai}=requireFirebaseAI();
  const generationConfig={responseModalities:[aiMod.ResponseModality.AUDIO],speechConfig:{voiceConfig:{prebuiltVoiceConfig:{voiceName:voice}},languageCode:'vi-VN'}};
  const model=aiMod.getGenerativeModel(ai,{model:'gemini-3.1-flash-tts-preview',generationConfig});
  const voiceNotes={Aoede:'warm, light Northern Vietnamese voice',Kore:'expressive, warm Southern Vietnamese voice',Zephyr:'natural, clear Northern Vietnamese voice',Callirrhoe:'steady standard Northern Vietnamese voice',Sulafat:'warm, conversational Vietnamese voice'};
  const prompt=`[Audio Profile: ${voiceNotes[voice]||'clear Vietnamese voice'}]\n[Director's Notes: Read the following Vietnamese text clearly and naturally, with a steady pace. Preserve the wording exactly.]\nTranscript:\n${text}`;
  const result=await model.generateContent(prompt),audioPart=result.response.inlineDataParts()?.find(part=>part.inlineData?.data);
  if(!audioPart)throw new Error('Gemini chưa trả về âm thanh. Hãy thử lại hoặc chia văn bản thành đoạn ngắn hơn.');
  const binary=atob(audioPart.inlineData.data),pcm=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)pcm[i]=binary.charCodeAt(i);
  return pcmToWav(pcm);
}
function signOutToAuth(){for(const key of ['inboxUnsubscribe','messageUnsubscribe','invoiceUnsubscribe'])if(state[key]){state[key]();state[key]=null}state.user=null;state.role='employee';for(const key of ['metrics','tasks','drafts','scripts','banned','reviews','templates','requests','invoices','dailyReports','revenueEntries','leaderboardRows','inboxThreads','messages','members','users','pages'])state[key]=[];state.activeThread=null;$('#app').classList.add('hidden');$('#authScreen').classList.remove('hidden')}
