    chart.innerHTML='<div class="leaderboard-summary-stats"><article><span>DOANH THU TOÀN KỲ</span><b>'+money(total)+'</b><small>Tất cả nhân sự có báo cáo</small></article><article><span>NHÂN SỰ CÓ BÁO CÁO</span><b>'+rows.length+'</b><small>Người</small></article><article><span>DẪN ĐẦU</span><b>'+esc(topUser.name)+'</b><small>'+money(topUser.revenue)+'</small></article><article><span>DOANH THU TRUNG BÌNH</span><b>'+money(average)+'</b><small>Trên mỗi nhân sự</small></article><article><span>LƯỢT NGÀY ĐÃ BÁO CÁO</span><b>'+reportedDays+'</b><small>Cộng theo từng nhân sự</small></article></div>';return;
