async function importCampaignData(value){let parsed=value;if(typeof value==='string'){const trimmed=value.trim();if(trimmed.startsWith('[')||trimmed.startsWith('{'))parsed=JSON.parse(trimmed);else parsed=parseCsv(trimmed)}const rows=Array.isArray(parsed)?parsed:(parsed.campaigns||parsed.data||parsed.rows||[parsed]);if(!Array.isArray(rows)||!rows.length)throw new Error('Không tìm thấy dòng chiến dịch trong dữ liệu.');const imported=assignMetricIds(rows.map(formatMetric));const unique=new Map();imported.forEach(row=>unique.set(row.id,row));const oldIds=new Set(state.metrics.map(row=>row.id));if(state.firebase)await Promise.all([...unique.values()].map(row=>saveRecord('campaigns',row,row.id)));else throw new Error('Chưa kết nối Firebase để lưu chỉ số.');const merged=new Map(state.metrics.map(row=>[row.id,row]));unique.forEach((row,id)=>merged.set(id,row));state.metrics=[...merged.values()];saveLocal();const preferred=imported[imported.length-1]?reportPeriodKey(imported[imported.length-1]):'';renderMetrics(preferred);closeModal();const updates=[...unique.keys()].filter(id=>oldIds.has(id)).length,added=unique.size-updates,collapsed=rows.length-unique.size;showToast('Đã thêm '+added+', cập nhật '+updates+(collapsed?', gộp '+collapsed+' dòng trùng':'')+'.')}
async function receiveExtensionImport(payload){
  if(!state.user||!state.firebase)throw new Error('Hãy đăng nhập website và kết nối Firebase trước khi chuyển dữ liệu.');
  if(payload?.kind==='metrics'){
    if(!Array.isArray(payload.campaigns)||!payload.campaigns.length)throw new Error('Extension không gửi được dòng chiến dịch nào.');
    const capturedDate=new Date(),todayKey=capturedDate.getFullYear()+'-'+String(capturedDate.getMonth()+1).padStart(2,'0')+'-'+String(capturedDate.getDate()).padStart(2,'0'),reportAt=/^\d{4}-\d{2}-\d{2}$/.test(String(payload.reportAt||''))?payload.reportAt:todayKey,campaigns=payload.campaigns.map(item=>({...item,reportAt:/^\d{4}-\d{2}-\d{2}$/.test(String(item.reportAt||''))?item.reportAt:reportAt}));
    navigate('analytics');await importCampaignData({source:'Marketing Ai FBTQ Meta Helper',campaigns});openDailyReportForm();return;
  }
  if(payload?.kind==='invoice-pdf'){
    if(!payload.base64||payload.base64.length>7_200_000)throw new Error('PDF rỗng hoặc vượt giới hạn 5 MB.');
    const binary=atob(payload.base64),bytes=new Uint8Array(binary.length);for(let index=0;index<binary.length;index++)bytes[index]=binary.charCodeAt(index);
    if(bytes.length>5*1024*1024||String.fromCharCode(...bytes.subarray(0,5))!=='%PDF-')throw new Error('Tệp chuyển từ Meta không phải PDF hợp lệ hoặc quá 5 MB.');
    navigate('automation');openMetaInvoiceUpload();const input=$('#metaInvoiceFile');if(!input)throw new Error('Không mở được form Upload Hóa Đơn Meta.');
    const file=new File([bytes],String(payload.filename||'meta-receipt.pdf').replace(/[\\/:*?"<>|]/g,'_'),{type:'application/pdf'}),transfer=new DataTransfer();transfer.items.add(file);input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));return;
  }
  throw new Error('Loại dữ liệu extension chưa được hỗ trợ.');
}
window.addEventListener('message',event=>{
  if(event.source!==window||event.origin!==location.origin||event.data?.type!=='FBTQ_EXTENSION_IMPORT')return;
  const payload=event.data.payload||{},deliveryId=payload.deliveryId||'';
  receiveExtensionImport(payload).then(()=>window.postMessage({type:'FBTQ_EXTENSION_IMPORT_RESULT',deliveryId,ok:true},location.origin)).catch(error=>{showToast(error.message||'Không nhận được dữ liệu từ extension.','error');window.postMessage({type:'FBTQ_EXTENSION_IMPORT_RESULT',deliveryId,ok:false},location.origin)});
});
function parseCsv(text){const input=String(text).replace(/^\uFEFF/,''),rows=[];let row=[],field='',quoted=false;for(let i=0;i<input.length;i++){const ch=input[i];if(quoted){if(ch==='"'&&input[i+1]==='"'){field+='"';i++}else if(ch==='"')quoted=false;else field+=ch;continue}if(ch==='"'&&field===''){quoted=true;continue}if(ch===','){row.push(field.trim());field='';continue}if(ch==='\n'||ch==='\r'){row.push(field.trim());if(row.some(cell=>cell!==''))rows.push(row);row=[];field='';if(ch==='\r'&&input[i+1]==='\n')i++;continue}field+=ch}row.push(field.trim());if(row.some(cell=>cell!==''))rows.push(row);if(rows.length<2)throw new Error('CSV cần có dòng tiêu đề và ít nhất một nhóm quảng cáo.');const headers=rows.shift().map((header,index)=>(index===0?header.replace(/^\uFEFF/,''):header).trim());return rows.map(values=>Object.fromEntries(headers.map((header,index)=>[header,values[index]??''])))}
