function openUserUnitEditor(uid){if(!isDirector())return showToast('Chỉ Giám đốc mới có thể gán chi nhánh.','error');const user=state.users.find(item=>item.uid===uid);if(!user)return showToast('Không tìm thấy hồ sơ thành viên.','error');openModal('Gán trụ sở hoặc chi nhánh',`<p>Thành viên cùng chi nhánh sẽ được gom chung trong Tổng quan. Để trống chi nhánh nếu hồ sơ chưa được phân đơn vị.</p><div class="modal-fields"><label>Chi nhánh / trụ sở<input name="branch" value="${esc(user.branch||user.branchName||user.branchId||'')}" placeholder="Ví dụ: Hà Nội, Tuyên Quang hoặc Trụ sở chính"></label><label>Phòng ban<input name="department" value="${esc(user.department||'')}" placeholder="Ví dụ: Marketing"></label></div>`,'Lưu đơn vị',async form=>{if(!state.firebase)throw new Error('Cần kết nối Firebase để lưu đơn vị thành viên.');const branch=String(form.get('branch')||'').trim(),department=String(form.get('department')||'').trim(),{db,storeMod}=state.firebase;await storeMod.setDoc(storeMod.doc(db,'users',uid),{branch,department,updatedAt:storeMod.serverTimestamp(),updatedBy:state.user.uid},{merge:true});const updated={...user,branch,department};state.users=state.users.map(item=>item.uid===uid?updated:item);if(state.user?.uid===uid)state.user={...state.user,branch,department};closeModal();renderPeople();renderMetrics();showToast('Đã lưu chi nhánh và phòng ban.')})}
function renderPeople(){syncAnalyticsUserControls();renderUserComparison();const body=$('#peopleTable');if(!body)return;const roleKeys={director:'roleCountDirector',branch_manager:'roleCountBranch',department_manager:'roleCountDepartment',employee:'roleCountEmployee'};for(const [role,id] of Object.entries(roleKeys)){const count=state.users.filter(user=>user.role===role).length;$('#'+id).textContent=count+' người'}const pending=state.users.filter(user=>user.approved===false).length;$('#peopleSummary').textContent=state.users.length+' tài khoản'+(pending?' · '+pending+' chưa kích hoạt':'');body.innerHTML=state.users.map(user=>{const displayName=user.name||user.email||'Tài khoản';const initials=displayName.split(/\s+/).filter(Boolean).slice(-2).map(part=>part[0]).join('').toUpperCase()||'NV';const role=user.role||'employee';const roleClass=role==='director'?'director-tag':role==='employee'?'staff-tag':'manager-tag';const active=user.approved!==false,branch=user.branch||user.branchName||user.branchId||'';return`<tr><td>${avatarMarkup(user.photoData,initials)}<span class="campaign-title"><b>${esc(displayName)}</b><small>${esc(user.email||'')}</small></span></td><td><span class="role-tag ${roleClass}">${esc(roleName(role))}</span></td><td>${esc(user.department||'—')}</td><td>${esc(branch||'Chưa gán')}<small class="unit-label">${branch?'Đơn vị báo cáo':'Cần gán để lọc theo chi nhánh'}</small></td><td><span class="status ${active?'status-live':'status-review'}">● ${active?'Đang hoạt động':'Chưa kích hoạt'}</span></td><td>${isDirector()?`<button type="button" class="text-button" data-edit-user-unit="${esc(user.uid)}">Sửa đơn vị</button>`:'—'}</td></tr>`}).join('')||'<tr><td colspan="6" class="muted">Chưa có hồ sơ thành viên trong Firebase.</td></tr>';$$('[data-edit-user-unit]').forEach(button=>button.addEventListener('click',()=>openUserUnitEditor(button.dataset.editUserUnit)))}
function renderContentQueuePreview(){const pending=[...state.reviews.filter(x=>x.status==='pending'),...state.templates.filter(x=>x.status==='pending')];$('#contentQueueCount').textContent=pending.length;$('#contentQueueList').innerHTML=pending.slice(0,3).map(x=>`<div class="approval-item"><span class="approval-dot"></span><div><b>${esc(x.title||'Nội dung đề xuất')}</b><small>${esc(x.createdByName||x.createdBy||'Nhân viên')}</small></div></div>`).join('')||'<p class="muted">Chưa có nội dung chờ duyệt.</p>'}
