function explainContentError(error){const raw=String(error?.message||error||'Không tạo được nội dung.'),lower=raw.toLowerCase();if(/app.?check|attestation|invalid token|401|403|permission_denied/.test(lower))return{title:'Firebase chưa xác thực được yêu cầu AI',help:'Kiểm tra App Check cho Firebase AI Logic: website phải dùng đúng reCAPTCHA Enterprise site key đã đăng ký với app Firebase và domain hosting. Sau khi sửa cấu hình, lưu thay đổi và tải lại trang.',detail:raw};if(/high demand|overload|temporarily unavailable|service unavailable|\b500\b|\b503\b|\b504\b|internal server error/.test(lower))return{title:'Gemini đang quá tải tạm thời',help:'Website đã tự thử lại và chuyển sang Gemini Flash-Lite dự phòng. Nếu lỗi vẫn còn, mô hình dự phòng cũng đang bận; hãy chờ một chút rồi thử lại.',detail:raw};if(/429|quota|resource_exhausted|rate.?limit/.test(lower))return{title:'Đã chạm giới hạn sử dụng AI',help:'Chờ một lúc rồi thử lại; nếu vẫn gặp lỗi, kiểm tra hạn mức Gemini Developer API của dự án Firebase.',detail:raw};if(/model.*(not found|unsupported)|404/.test(lower))return{title:'Mô hình AI hiện không khả dụng',help:'Kiểm tra Firebase AI Logic đã bật Gemini Developer API và tên mô hình còn được hỗ trợ trong dự án.',detail:raw};return{title:'Chưa tạo được phản hồi AI',help:'Kiểm tra kết nối Firebase và cấu hình Firebase AI Logic, sau đó thử lại. Chi tiết lỗi bên dưới có thể giúp xác định nguyên nhân.',detail:raw}}
function showContentGenerationError(error){const panel=$('#resultPanel'),info=explainContentError(error);panel.setAttribute('aria-live','assertive');panel.innerHTML=`<div class="generation-error"><div class="generation-error-icon">!</div><div class="generation-error-copy"><b>${esc(info.title)}</b><p>${esc(info.help)}</p><details><summary>Chi tiết lỗi</summary><code>${esc(info.detail)}</code></details><button type="button" class="btn btn-secondary" id="retryContent">↻ Thử tạo lại</button></div></div>`;$('#retryContent').addEventListener('click',()=>$('#generateContent').click());scrollContentResult()}
function showGenerated(title,text){const panel=$('#resultPanel');panel.setAttribute('aria-live','polite');panel.innerHTML=`<div class="result-generated"><div class="generated-head"><div class="generated-title"><span class="result-ai-mark">✦</span><b>Phản hồi AI</b></div><span class="status status-neutral">BẢN NHÁP</span></div><div class="generated-prompt-label">${esc(title)}</div><div class="generated-content" contenteditable="true" aria-label="Nội dung do AI tạo">${esc(text)}</div><div class="generated-actions"><button class="btn btn-secondary" id="saveDraft">▤ Lưu nháp</button><button class="btn btn-secondary" id="copyContent">▣ Sao chép</button><button class="btn btn-secondary" id="sendToSpeech">🔊 Tạo giọng đọc</button><button class="btn btn-primary manager-review">⇧ Gửi quản lý duyệt</button></div></div>`;$('#saveDraft').addEventListener('click',()=>saveDraft(title,$('.generated-content').innerText));$('#copyContent').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('.generated-content').innerText);showToast('Đã sao chép nội dung.')}catch{showToast('Trình duyệt chưa cho phép clipboard.','error')}});$('#sendToSpeech').addEventListener('click',()=>{const content=$('.generated-content').innerText;$('#speechText').value=content;updateSpeechCount();$$('[data-editor-tab]').find(x=>x.dataset.editorTab==='speech').click();$('#speechText').focus();showToast('Đã chuyển bản nháp sang tab Giọng đọc trong Studio Nội Dung.')});$('.manager-review').addEventListener('click',async()=>{if(state.firebase)await saveRecord('contentReviews',{title,text:$('.generated-content').innerText,status:'pending'});showToast('Đã gửi nội dung vào hàng chờ quản lý duyệt.');$('.manager-review').textContent='✓ Đã gửi duyệt';$('.manager-review').disabled=true});scrollContentResult()}
