function updateMetaInvoiceCheck(){const status=$('#metaInvoiceValidation');if(!status)return;const subtotal=Number($('#activeModalForm [name="amountBeforeVat"]')?.value||0),vat=Number($('#activeModalForm [name="vatAmount"]')?.value||0),total=Number($('#activeModalForm [name="total"]')?.value||0);let message='Kiểm tra ID giao dịch, ngày hóa đơn, VAT Rate và tổng thanh toán trước khi gửi duyệt.',tone='info';if(total>0&&Math.abs(subtotal+vat-total)>1){message=`Tiền trước VAT + VAT là ${money(subtotal+vat)}, nhưng tổng thanh toán là ${money(total)}. Vui lòng kiểm tra lại PDF.`;tone='warning'}else if(total>0){message='Tổng tiền trước VAT và VAT đang khớp với tổng thanh toán. Hãy đối chiếu lại PDF trước khi gửi.';tone='success'}status.textContent=message;status.className=`meta-invoice-validation ${tone}`}
